#!/usr/bin/env node
// Check that requirements.txt, generated by `make lock`, pins every package in requirements.in, and that every
// pin carries hashes (docs/design/dependency-pinning.md). Reads only the two files, so it needs no network.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** PyPI's normalised project name: lowercase, with runs of `-`, `_` and `.` as one `-`. */
export function normalise(name) {
  return name.toLowerCase().replace(/[-_.]+/g, "-");
}

/** The project names in a requirements.in, ignoring comments, blank lines and options. */
export function directNames(text) {
  return text
    .split("\n")
    .map((line) => line.replace(/#.*/, "").trim())
    .filter((line) => line && !line.startsWith("-"))
    .map((line) => normalise(line.match(/^[A-Za-z0-9][A-Za-z0-9._-]*/)[0]));
}

/** Each pinned package in a generated lock, with whether its pin has at least one hash. */
export function pins(text) {
  const found = new Map();
  let current = null;
  for (const line of text.split("\n")) {
    const pin = line.match(/^([A-Za-z0-9][A-Za-z0-9._-]*)==\S+/);
    if (pin) {
      current = normalise(pin[1]);
      found.set(current, found.get(current) || false);
    } else if (current && /^\s+--hash=sha256:[0-9a-f]{64}/.test(line)) {
      found.set(current, true);
    } else if (!/^\s/.test(line)) {
      current = null;
    }
  }
  return found;
}

/** Problems with a lock, as messages; empty when it pins every direct dependency with hashes. */
export function checkLock(inText, lockText) {
  const locked = pins(lockText);
  const problems = [];
  for (const name of directNames(inText)) {
    if (!locked.has(name))
      problems.push(
        `${name} is in requirements.in but not pinned in requirements.txt`,
      );
  }
  for (const [name, hashed] of locked) {
    if (!hashed) problems.push(`${name} is pinned without a hash`);
  }
  if (!locked.size) problems.push("requirements.txt pins nothing");
  return problems;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const problems = checkLock(
    readFileSync("requirements.in", "utf8"),
    readFileSync("requirements.txt", "utf8"),
  );
  if (problems.length) {
    console.error(problems.join("\n"));
    console.error("\nRun `make lock` to regenerate requirements.txt.");
    process.exit(1);
  }
  console.log(
    "PASS requirements.txt pins every package in requirements.in, with hashes",
  );
}
